"""Exact retained AgentStore construction and close policy; offline authoring only."""

class AgentStore:
    def __init__(self, root):
        from .hia_execution_budget import admitted_execution_budget, execution_budget_store
        from .hia_request_journal_native import admitted_request_journal, request_journal_store
        from .hia_artifact_namespace_native import admitted_artifact_namespace, artifact_namespace_store
        from .hia_slot_ledger_continuation_native import admitted_slot_ledger, slot_ledger_store
        budget_admission = admitted_execution_budget()
        request_admission = admitted_request_journal()
        namespace_admission = admitted_artifact_namespace()
        ledger_admission = admitted_slot_ledger(namespace_admission=namespace_admission,
                                                request_admission=request_admission)
        supplied = Path(root).absolute()
        supplied.mkdir(mode=0o700, parents=True, exist_ok=True)
        if supplied.is_symlink():
            reject("E_HIA_STORE", "state directory cannot be a symbolic link")
        self.root = supplied.resolve()
        info = self.root.stat()
        if info.st_uid != os.geteuid() or info.st_mode & 0o022:
            reject("E_HIA_STORE", "state directory must be owned and not writable by other users")
        self.artifacts = self.root / "artifacts"
        self.artifacts.mkdir(mode=0o700, exist_ok=True)
        if self.artifacts.is_symlink():
            reject("E_HIA_STORE", "artifact directory cannot be a symbolic link")
        info = self.artifacts.lstat()
        if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.geteuid() or info.st_mode & 0o022:
            reject("E_HIA_STORE", "artifact directory must be owned and not writable by other users")
        database = self.root / "state.sqlite3"
        if database.exists() or database.is_symlink():
            info = database.lstat()
            if not stat.S_ISREG(info.st_mode) or info.st_uid != os.geteuid() or info.st_mode & 0o022:
                reject("E_HIA_STORE", "journal must be an owned private ordinary file")
        self.db = sqlite3.connect(database, isolation_level=None, timeout=10, check_same_thread=False)
        os.chmod(database, 0o600)
        self.database = database
        database_info = database.lstat()
        if not stat.S_ISREG(database_info.st_mode):
            reject('E_HIA_STORE', 'journal must remain an ordinary file after opening')
        self.database_identity = (database_info.st_dev, database_info.st_ino)
        self.db.row_factory = sqlite3.Row
        self.db.execute("PRAGMA journal_mode=WAL")
        self.db.execute("PRAGMA synchronous=FULL")
        self.lock = threading.RLock()
        self.db.executescript("""
            CREATE TABLE IF NOT EXISTS artifacts (
                id TEXT PRIMARY KEY, sha256 TEXT NOT NULL, uri TEXT UNIQUE NOT NULL,
                kind TEXT NOT NULL, metadata TEXT NOT NULL, content_key TEXT UNIQUE NOT NULL
            );
            CREATE TABLE IF NOT EXISTS profiles (
                id TEXT NOT NULL, sha256 TEXT NOT NULL, artifact TEXT NOT NULL,
                PRIMARY KEY (id,sha256)
            );
            CREATE TABLE IF NOT EXISTS contexts (
                id TEXT PRIMARY KEY, sha256 TEXT NOT NULL, artifact TEXT NOT NULL,
                created_ns TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS requests (
                key TEXT PRIMARY KEY, digest TEXT NOT NULL, tool TEXT NOT NULL,
                state TEXT NOT NULL, response TEXT, started_ns TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS costs (
                sequence INTEGER PRIMARY KEY AUTOINCREMENT, context_id TEXT,
                tool TEXT NOT NULL, request_id TEXT NOT NULL, wall_ns TEXT NOT NULL,
                status TEXT NOT NULL, details TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS cursors (
                id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL,
                sha256 TEXT NOT NULL, offset INTEGER NOT NULL
            );
            CREATE TABLE IF NOT EXISTS slots (
                name TEXT PRIMARY KEY, context_id TEXT NOT NULL,
                generation TEXT NOT NULL, epoch TEXT NOT NULL, abi_sha256 TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS versions (
                slot TEXT NOT NULL, generation TEXT NOT NULL, artifact TEXT NOT NULL,
                PRIMARY KEY (slot,generation)
            );
            CREATE TABLE IF NOT EXISTS leases (
                id TEXT PRIMARY KEY, slot TEXT NOT NULL, generation TEXT NOT NULL,
                artifact TEXT NOT NULL, active INTEGER NOT NULL
            );
            CREATE TABLE IF NOT EXISTS execution_budgets (
                context_id TEXT PRIMARY KEY, used_native_ns TEXT NOT NULL,
                owner TEXT
            );
        """)
        self.execution_budgets = None
        self.request_journal = None
        self.artifact_namespace = None
        self.slot_ledger = None
        try:
            self.database_sidecars = None
            if budget_admission is not None or request_admission is not None or namespace_admission is not None:
                # Capture the official connection's WAL namespace before a second
                # connection can open it. Never adopt a replacement sidecar as the
                # identity merely because a new connection can read it.
                self.db.execute('SELECT name FROM sqlite_master LIMIT 1').fetchone()
                sidecars = {}
                for suffix in ('-wal', '-shm'):
                    sidecar = Path(str(database) + suffix).lstat()
                    if (not stat.S_ISREG(sidecar.st_mode) or sidecar.st_uid != os.geteuid()
                            or sidecar.st_mode & 0o022):
                        reject('E_HIA_STORE', 'journal sidecar must be an owned private ordinary file')
                    sidecars[suffix] = (sidecar.st_dev, sidecar.st_ino)
                self.database_sidecars = sidecars
            self.execution_budgets = execution_budget_store(self, budget_admission)
            if namespace_admission is None:
                self.request_journal = request_journal_store(self, request_admission)
            else:
                self.request_journal = request_journal_store(self, request_admission, shared_lock=self.lock)
            self.artifact_namespace = artifact_namespace_store(self, namespace_admission)
            self.slot_ledger = slot_ledger_store(self, ledger_admission)
        except BaseException as error:
            # Construction retains the main cleanup boundary. Close only owners
            # actually returned by earlier admissions, in ordinary close order.
            for owner in (self.slot_ledger, self.artifact_namespace,
                          self.request_journal, self.execution_budgets):
                if owner is not None:
                    try:
                        owner.close()
                    except BaseException as failure:
                        error.add_note('AgentStore construction cleanup failed: ' + type(failure).__name__)
            try:
                self.db.close()
            except BaseException as failure:
                error.add_note('AgentStore construction cleanup failed: ' + type(failure).__name__)
            raise

    def close(self):
        if self.slot_ledger is not None:
            self.slot_ledger.close()
        if self.artifact_namespace is not None:
            self.artifact_namespace.close()
        if self.request_journal is not None:
            self.request_journal.close()
        self.execution_budgets.close()
        self.db.close()

"""Complete six-body store-lifecycle continuation authoring.

Uses the reviewed Build lexical cell/named-function mechanism and the reviewed
Verification DICT_MERGE/DICT_UPDATE policy. The runtime receives no AST.
"""
from __future__ import annotations
import ast
import struct
from types import CodeType
from tools.hia_native_build_control import Compiler as BuildCompiler, Function as BuildFunction
from tools.hia_machine_plan_control import OPS, PACK, COMPARE

METHODS = ('__init__', 'close')
ENTRIES = METHODS
DICT_UPDATE = 253
MAPPING_PREPARE = 254
MAPPING_CALL = 255


class Compiler(BuildCompiler):
    def __init__(self, source):
        self.source, self.tree = source, ast.parse(source)
        # Handler routing is encoded per effect instruction. A loop jump out
        # of a try BODY needs no dynamic pop; it has never entered HANDLED.
        # The retained page loops only break from successful try bodies.
        # A jump/return out of an except or a finally region would need a
        # separate cleanup protocol and remains explicitly unreviewed.
        for node in ast.walk(self.tree):
            if isinstance(node, (ast.AsyncWith, ast.TryStar)):
                raise ValueError('store-lifecycle policy has an unreviewed cleanup region')
            if isinstance(node, ast.Try):
                if (len(node.handlers) != 1 or node.orelse or node.finalbody
                        or node.handlers[0].type is None):
                    raise ValueError('store-lifecycle policy has an unreviewed exception region')
                if any(isinstance(child, (ast.Break, ast.Continue, ast.Return))
                       for statement in node.handlers[0].body for child in ast.walk(statement)):
                    raise ValueError('store-lifecycle policy has an unreviewed handled-exception exit')
        self.lexical_codes = {}
        def remember(code):
            for child in code.co_consts:
                if isinstance(child, CodeType):
                    key = (child.co_firstlineno, child.co_name)
                    if key in self.lexical_codes:
                        raise ValueError('ambiguous store-lifecycle lexical frame')
                    self.lexical_codes[key] = child
                    remember(child)
        remember(compile(source, '<store-lifecycle-lexical-layout>', 'exec'))
        self.imports = {}
        for node in ast.walk(self.tree):
            if isinstance(node, ast.ImportFrom):
                if node.level != 1:
                    raise ValueError('store-lifecycle import must be package-relative')
                self.imports.setdefault(node.module, set()).update(alias.name for alias in node.names)
        self.literals, self.literal_indices = [], {}
        self.functions, self.by_name = [], {}
        classes = [node for node in self.tree.body if isinstance(node, ast.ClassDef)]
        if (len(classes) != 1 or classes[0].name != 'AgentStore'
                or tuple(getattr(node, 'name', None) for node in classes[0].body) != METHODS
                or any(isinstance(node, ast.FunctionDef) for node in self.tree.body)):
            raise ValueError('complete store-lifecycle policy inventory differs')
        for node in classes[0].body:
            expected = []
            if (not isinstance(node, ast.FunctionDef)
                    or [ast.dump(d) for d in node.decorator_list] != [ast.dump(d) for d in expected]):
                raise ValueError('store-lifecycle policy declaration differs')
            function = Function(self, node.name, node)
            self.functions.append(function)
            self.by_name[node.name] = function
        index = 0
        while index < len(self.functions):
            self.functions[index].compile()
            index += 1
        for mode, function in enumerate(self.functions, 1):
            function.mode = mode
        for function in self.functions:
            function.resolve()
        self._validate_calls()

    def literal(self, value):
        if type(value) is float:
            # Distinct IEEE payloads, especially +0 and -0, must not collapse
            # under Python's value equality. Each emitted index is boxed once.
            key = (float, struct.pack('<d', value))
            if key not in self.literal_indices:
                self.literal_indices[key] = len(self.literals)
                self.literals.append(value)
            return self.literal_indices[key]
        return super().literal(value)

    def nested(self, parent, node, kind):
        if kind not in ('function', 'generator', 'lambda'):
            raise ValueError('store-lifecycle lexical child kind differs')
        function = Function(self, parent.name + ':' + kind + ':' + str(len(self.functions)),
                            node, parent=parent, kind=kind)
        self.functions.append(function)
        return function


    def region(self, parent, node):
        function = Function(self, parent.name+':with:'+str(len(self.functions)),
                            node, parent=parent, kind='with_region')
        self.functions.append(function)
        return function


class Function(BuildFunction):
    def expression(self, node):
        if isinstance(node, ast.BoolOp):
            result, done = self.slot(), self.label()
            for index, child in enumerate(node.values):
                self.store(result, self.expression(child))
                if index != len(node.values) - 1:
                    onward = self.label()
                    self.truth(self.copy(result),
                               onward if isinstance(node.op, ast.And) else done,
                               done if isinstance(node.op, ast.And) else onward)
                    self.mark(onward)
                    # JUMP_IF_*_OR_POP discards the first value before the
                    # next expression. Keep it only on the short-circuit edge,
                    # where the caller may truth-test that same object again.
                    self.release((result,))
            self.mark(done)
            return result
        if isinstance(node, ast.Call):
            if any(isinstance(arg, ast.Starred) for arg in node.args):
                raise ValueError('store-lifecycle policy has no starred positional call')
            mappings = [i for i, keyword in enumerate(node.keywords) if keyword.arg is None]
            callee = self.expression(node.func)
            arguments = [self.expression(arg) for arg in node.args]
            if mappings:
                if mappings != [len(node.keywords)-1] or len(mappings) != 1:
                    raise ValueError('store-lifecycle mapping must be the one final expansion')
                explicit = node.keywords[:-1]
                if tuple(k.arg for k in explicit) not in ((), ('kind',)):
                    raise ValueError('store-lifecycle explicit mapping-keyword shape differs')
                # CALL_FUNCTION_EX constructs the positional tuple before
                # evaluating the keyword mapping. Its objects then outlive
                # the original operand temporaries under that same tuple.
                positional = self.effect('PACK', raw=(PACK['Tuple'],),
                                         vector=arguments, consume=reversed(arguments))
                values = [self.expression(k.value) for k in explicit]
                mapping = self.expression(node.keywords[-1].value)
                prepared = self.effect('CALL', (callee, positional, *values, mapping),
                    raw=(len(explicit), MAPPING_PREPARE),
                    consume=(*reversed(values), mapping))
                return self.effect('CALL', (callee, positional, prepared),
                                   raw=(0, MAPPING_CALL), consume=(callee, positional, prepared))
            keys = [self.compiler.literal(k.arg) for k in node.keywords]
            values = [self.expression(k.value) for k in node.keywords]
            if len(arguments) > 5 or len(keys) > 8:
                raise ValueError('store-lifecycle fixed call extent differs')
            return self.effect('CALL', (callee, *arguments, *values),
                               raw=(len(arguments), len(keys), *keys),
                               consume=(callee, *arguments, *values))
        if isinstance(node, ast.Dict) and any(key is None for key in node.keys):
            result = self.effect('PACK', raw=(PACK['Dict'],), vector=())
            pending_keys, pending_values = [], []
            def flush():
                if pending_keys:
                    block = super(Function, self).expression(ast.Dict(
                        keys=list(pending_keys), values=list(pending_values)))
                    self.effect('CALL', (result, block), raw=(0, DICT_UPDATE),
                                destination=result, consume=(block,))
                    pending_keys.clear(); pending_values.clear()
            for key, value in zip(node.keys, node.values):
                if key is None:
                    flush()
                    mapping = self.expression(value)
                    self.effect('CALL', (result, mapping), raw=(0, DICT_UPDATE),
                                destination=result, consume=(mapping,))
                else:
                    if not isinstance(key, ast.Constant) or type(key.value) is not str:
                        raise ValueError('store-lifecycle expanded dictionary key shape differs')
                    pending_keys.append(key); pending_values.append(value)
            flush()
            return result
        return super().expression(node)


    def statements(self, statements):
        for node in statements:
            if isinstance(node, ast.Delete):
                for target in node.targets:
                    if not isinstance(target, ast.Name):
                        raise ValueError('store-lifecycle policy only deletes named lexical bindings')
                    value = self.variable(target.id)
                    if value is None:
                        raise ValueError('artifact deletion lacks an original lexical binding')
                    name, role = self.read_kinds[value.slot]
                    if name != target.id:
                        raise ValueError('artifact deletion lexical identity differs')
                    self.effect('STORE', (value,), raw=(2, self.compiler.literal(name), role), count=0)
            elif isinstance(node, ast.For):
                iterable = self.expression(node.iter)
                iterator = self.effect('ITER', (iterable,), consume=(iterable,))
                head, found, exhausted, broken, done = (self.label() for _ in range(5))
                self.mark(head)
                value = self.effect('NEXT', (iterator,))
                self.emit('flag', yes=found, no=exhausted)
                self.mark(found)
                self.assign(node.target, value)
                # Continue resumes the same iterator. Break owns only the
                # nearest loop exit; it retires that iterator before the
                # following statement and bypasses the normal else body.
                self.loop_stack.append((head, broken))
                self.statements(node.body)
                self.loop_stack.pop()
                self.jump(head)
                self.mark(exhausted)
                self.release((value, iterator))
                self.statements(node.orelse)
                self.jump(done)
                self.mark(broken)
                self.release((value, iterator))
                self.mark(done)
            elif isinstance(node, ast.While):
                if node.orelse:
                    raise ValueError('request while-else has no reviewed cleanup contract')
                super().statements((node,))
            elif isinstance(node, ast.Break):
                if not self.loop_stack:
                    raise ValueError('store-lifecycle break has no owning loop')
                self.jump(self.loop_stack[-1][1])
            else:
                super().statements((node,))



def compile_policy(source):
    return Compiler(source)

"""Generate both exact AgentStore lifecycle policies."""
from __future__ import annotations

import argparse
import ast
from pathlib import Path
import sys
import struct

ROOT = Path(__file__).resolve().parents[1]
if __package__ in (None, ''):
    sys.path.insert(0, str(ROOT))

from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions
from tools.generate_hia_machine_plan_control import (
    BODY as CONTROL_BODY, MAGIC, EMIT_MAGIC, ABI, OUTPUT)
from tools.generate_hia_core_lowering_control import emission, transport_helpers
from tools.hia_core_lowering_table import BODY as EXPAND_BODY, compress_table, reference_expand
from tools.hia_exception_delivery import BODY as EXCEPTION_BODY
from tools.hia_store_lifecycle_control import compile_policy, OPS


def table(policy):
    starts = {}
    count = 0
    for function in policy.functions:
        starts[function.mode] = count + 1
        count += len(function.instructions)
    data = bytearray(64 + len(policy.functions) * 32)
    for function in policy.functions:
        metadata = len(data)
        data += bytes((int(i in function.temporary_slots) |
                       (2 * int(i in function.cell_slots)))
                      for i in range(function.next_slot))
        for own, outer in function.captures.values():
            data += struct.pack('<H', own.slot)
        info = (len(function.parameters) |
                (int(function.kind == 'generator') << 16) |
                (len(function.captures) << 32))
        struct.pack_into('<4Q', data, 64 + (function.mode - 1) * 32,
                         starts[function.mode], function.next_slot, info, metadata)
    offsets_at = len(data)
    data += b'\0' * (4 * count)
    ordinal = 0
    for function in policy.functions:
        shift = starts[function.mode] - 1
        for instruction in function.instructions:
            struct.pack_into('<I', data, offsets_at + ordinal * 4, len(data))
            ordinal += 1
            kind = instruction['kind']
            if kind == 'effect':
                destinations, arguments = instruction['destinations'], instruction['arguments']
                raw, vector = instruction['raw'], instruction['vector']
                consume = instruction['consume']
                handler = instruction['handler']
                data += struct.pack('<6BH I H', 1, instruction['opcode'], len(destinations),
                                    len(arguments), len(raw), len(consume), len(vector),
                                    handler + shift if handler else 0, 0)
                for ref in (*destinations, *arguments):
                    data += struct.pack('<H', ref.slot)
                for value in raw:
                    data += struct.pack('<I', value)
                for ref in (*vector, *consume):
                    data += struct.pack('<H', ref.slot)
            elif kind == 'jump':
                data += struct.pack('<BI', 2, instruction['target'] + shift)
            elif kind == 'flag':
                data += struct.pack('<BII', 3, instruction['yes'] + shift,
                                    instruction['no'] + shift)
            elif kind in ('return', 'yield'):
                data += struct.pack('<BH', 4 if kind == 'return' else 5,
                                    instruction['value'].slot)
            elif kind == 'error_return':
                data += b'\6'
            else:
                raise ValueError('unrendered instruction')
    literals_at = len(data)
    data += b'\0' * (4 * len(policy.literals))
    for index, value in enumerate(policy.literals):
        struct.pack_into('<I', data, literals_at + 4 * index, len(data))
        if value is None:
            kind, raw = 0, b''
        elif type(value) is bool:
            kind, raw = 1, bytes((int(value),))
        elif type(value) is int:
            kind, raw = 2, str(value).encode('ascii')
        elif type(value) is bytes:
            kind, raw = 5, value
        elif type(value) is float:
            kind, raw = 6, struct.pack('<d', value)
        elif type(value) is str:
            # CPython interns its ASCII name-character constants. Record that
            # representation in the immutable HIA-owned table, so the runtime
            # bridge does not infer a policy or change the object's identity.
            interned = all(c in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'
                           for c in value)
            kind, raw = (4 if interned else 3), value.encode('utf-8')
        else:
            raise ValueError('unrendered literal')
        data += struct.pack('<BQ', kind, len(raw)) + raw
    data += bytes((-len(data)) % 8)
    struct.pack_into('<8Q', data, 0, MAGIC, len(data), len(policy.functions), count,
                     64, offsets_at, literals_at, len(policy.literals))
    return bytes(data)


def program():
    return compile_policy((ROOT / 'tools/hia_store_lifecycle_policy.py').read_text())


def source():
    policy = program()
    data = table(policy)
    packed = compress_table(data)
    if reference_expand(packed) != data:
        raise AssertionError('store-lifecycle policy representation is not lossless')
    constants = {'MAGIC': MAGIC, 'EMIT_MAGIC': EMIT_MAGIC, 'ABI': ABI,
                 'OUTPUT_BYTES': OUTPUT, 'TABLE_BYTES': len(data),
                 'PACKED_BYTES': len(packed),
                 'WORKSPACE_BYTES': 1024 + 8 * max(fn.next_slot for fn in policy.functions),
                 **OPS}
    parsed = ast.parse(CONTROL_BODY + '\n' + transport_helpers() + '\n' +
                       emission(data, packed) + '\n' + EXPAND_BODY + '\n' + EXCEPTION_BODY)
    class Names(ast.NodeTransformer):
        def visit_Name(self, node):
            return ast.copy_location(ast.Constant(constants[node.id]), node) if node.id in constants else node
    return ast.fix_missing_locations(Names().visit(parsed))


def document():
    nodes = source().body
    names = {node.name: 'f' + str(index) for index, node in enumerate(nodes)}
    signatures = {node.name: ([arg.annotation.id for arg in node.args.args], node.returns.id)
                  for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = Builder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({'name': names[node.name], 'params': [builder.param(v) for v in builder.params],
            'returns': [builder.returns], 'effects': ['read', 'write', 'trap'],
            'entry': 'b0', 'blocks': builder.blocks})
    return compact_authoring_cfg({'schema': 'hepta.hia.program.v8',
                                  'module': 'store_lifecycle', 'functions': functions})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path,
                        default=ROOT / 'examples/hia_bootstrap/store_lifecycle.hepta')
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    raw = render_assembly(document()).encode()
    if args.check:
        if args.output.read_bytes() != raw:
            raise AssertionError('store-lifecycle HIA differs from its complete policy')
    else:
        args.output.write_bytes(raw)
    print(args.output)


if __name__ == '__main__':
    main()

"""Fixed CPython CALL/IMPORT/name-error ports, without Store policy.

HIA chooses the operation, operands, order and one-use effect permission.
No Store body or SQLite policy is interpreted or compiled by this bridge.
"""
from __future__ import annotations
import dis
import sys
from types import FunctionType

def _profile():
    if sys.implementation.name != 'cpython' or sys.version_info[:2] not in ((3, 12), (3, 13), (3, 14)):
        raise RuntimeError('store-lifecycle ports require a reviewed CPython ABI')


TABLE_SHA256 = '72a1a61e0c0fba8b197fba969dd8a2b5e5ecd3f066f9e2cbd74ff537885e3ed5'

FUNCTION_LAYOUT = ((1, 'function', 364, 2, 0), (2, 'function', 34, 1, 0))
IMPORT_NAMES = ('admitted_artifact_namespace', 'admitted_execution_budget', 'admitted_request_journal', 'admitted_slot_ledger', 'artifact_namespace_store', 'execution_budget_store', 'request_journal_store', 'slot_ledger_store')
def _import_name_port(template, namespace, module, fromlist, level):
    _profile()
    code = template.__code__
    meaningful = tuple(i for i in dis.get_instructions(code, show_caches=True, adaptive=False)
                       if i.opname != 'CACHE')
    imports = tuple(i for i in meaningful if i.opname == 'IMPORT_NAME')
    if code.co_exceptiontable or len(imports) != 1 or imports[0].argval != module:
        raise RuntimeError('store-lifecycle IMPORT_NAME template differs')
    prefix = tuple(i for i in meaningful if i.offset <= imports[0].offset)
    if (tuple(i.opname for i in prefix) not in (
            ('RESUME', 'LOAD_CONST', 'LOAD_CONST', 'IMPORT_NAME'),
            ('RESUME', 'LOAD_SMALL_INT', 'LOAD_CONST', 'IMPORT_NAME'))
            or prefix[1].argval != level or prefix[2].argval != fromlist):
        raise RuntimeError('store-lifecycle original import operands differ')
    raw = code.co_code[:imports[0].offset + 2] + bytes((dis.opmap['RETURN_VALUE'], 0))
    return FunctionType(code.replace(co_code=raw, co_name='_store_lifecycle_import_name',
                                    co_qualname='_store_lifecycle_import_name'), namespace)

def _from_template(module):
    return module.ARTIFACT_PROFILE

def _import_from_port(name, namespace):
    _profile()
    if name not in IMPORT_NAMES:
        raise RuntimeError('store-lifecycle imported name is outside the fixed inventory')
